import{t as e}from"./jsx-runtime-lw2jiZar.js";import{C as t,D as n,E as r,M as i,N as a,O as o,P as s,T as c,b as l,j as u,k as d,l as f,n as p,o as m,p as h,t as g,v as _}from"./shared-C5BCElVa.js";import{t as v}from"./server-Cjp83m3Q.js";import{M as y}from"./index-D5bsO7MS.js";import{t as b}from"./CodeEditor-BZlrvoTL.js";var x=e(),S=`Этап 4 · Блок 13 · FastAPI как цельное приложение`;function C({module:e}){return(0,x.jsxs)(a,{children:[(0,x.jsx)(i,{variant:`project`,chip:e??S,title:`Заголовки и Response`,intro:`Продолжим существующий Planner небольшим HTTP-ресурсом. Разделим значение, которое клиент прислал в заголовке, JSON-ответ и диагностическую метку, которую задаёт само приложение.`,tags:[{icon:(0,x.jsx)(y,{size:14}),label:`HTTP-контракт`},{icon:(0,x.jsx)(v,{size:14}),label:`ответ сервера`}]}),(0,x.jsxs)(s,{number:`00`,title:`От заголовка запроса к ресурсу Planner`,children:[(0,x.jsx)(o,{children:`В Planner уже есть API задач, JSON-ответы и проверки HTTP-контракта. Теперь мы добавим рядом небольшой ресурс, который сообщает режим представления по умолчанию и принимает диагностическую версию клиента.`}),(0,x.jsx)(d,{variant:`connected`,items:[{title:`Точка старта`,description:`FastAPI принимает запросы, а знакомые body и status уже описывают данные и результат операции.`},{title:`Новый вопрос`,description:`Как принять необязательный X-Client-Version и добавить отдельный серверный X-Planner-Version?`},{title:`Результат`,description:`GET /preferences возвращает default view и клиентское значение, не меняя задачи или их хранилище.`}]}),(0,x.jsx)(`p`,{children:`Мы применим уже знакомую границу HTTP к новой операции. Входная версия останется данными запроса, а метка Planner будет определяться приложением. Это важно различать, даже если оба значения выглядят как короткие строки.`}),(0,x.jsx)(`p`,{children:`Сначала отделим части обмена, затем проследим путь необязательного заголовка, разберём ограничения и настройку ответа. После этого соберём ресурс в существующем приложении и проверим, что новый маршрут не изменил прежний API.`})]}),(0,x.jsxs)(s,{number:`01`,title:`Body, status и headers сообщают разное`,children:[(0,x.jsx)(o,{children:`Один HTTP-ответ можно рассматривать сразу с нескольких сторон. Статус говорит, как завершился запрос, body несёт результат операции, а headers передают метаданные обмена.`}),(0,x.jsx)(`p`,{children:`Для нового GET /preferences ожидаемый JSON содержит view со значением compact и client_version со строкой, которую прислал клиент, либо null, если заголовка нет. Успешная операция возвращает обычный статус 200. Отдельно ответ включает X-Planner-Version, установленный приложением.`}),(0,x.jsx)(`p`,{children:`Разделение помогает понять, что именно проверять. Если мы смотрим только на body, то не замечаем ошибочное имя заголовка. Если смотрим только на status 200, не видим, что сервер случайно вернул клиентскую версию вместо своей. Поэтому статус, JSON и headers подтверждают разные части договора.`}),(0,x.jsx)(`p`,{children:`Представим письмо в конверте: текст письма похож на body, отметка о доставке на status, а служебная наклейка на конверте на header. Наклейка помогает маршрутизации, но не становится частью текста письма. Граница аналогии в том, что HTTP-статус не является физической отметкой: это отдельное поле протокола, которое клиент читает структурно.`}),(0,x.jsx)(h,{prompt:`Сопоставим наблюдение с его ролью в ответе.`,leftTitle:`Часть обмена`,rightTitle:`Что сообщает`,pairs:[{left:(0,x.jsx)(`code`,{children:`status_code`}),right:`Результат обработки запроса`},{left:(0,x.jsx)(`code`,{children:`response.json()`}),right:`Данные body`},{left:(0,x.jsx)(`code`,{children:`X-Planner-Version`}),right:`Диагностическая метка в header`}],explanation:`Мы разделяем эти наблюдения, потому что изменение одного не гарантирует правильность двух остальных.`}),(0,x.jsx)(r,{tone:`info`,children:`X-Client-Version и X-Planner-Version принадлежат разным направлениям обмена: первый приходит от клиента, второй задаёт сервер.`})]}),(0,x.jsxs)(s,{number:`02`,title:`Необязательный Header становится параметром функции`,children:[(0,x.jsx)(o,{children:`FastAPI читает значение заголовка до вызова обработчика и передаёт его обычным аргументом. Мы задаём Python-имя параметра и отдельно указываем HTTP-имя через alias.`}),(0,x.jsx)(`p`,{children:`В HTTP обычно используют дефисы, а в Python именах переменных удобны подчёркивания. Например, параметр client_region может читать X-Client-Region. Явный alias связывает эти два написания и делает публичный договор очевидным в коде.`}),(0,x.jsx)(`p`,{children:`Параметр можно сделать необязательным. Если клиент не прислал заголовок, значение по умолчанию будет None. Если прислал пустое значение, мы получим пустую строку. Это разные входы: None означает отсутствие, а пустая строка означает, что заголовок был передан без текста.`}),(0,x.jsx)(b,{caption:`Независимый пример: язык страницы статуса`,code:`from typing import Annotated
from fastapi import FastAPI, Header

app = FastAPI()

@app.get('/status')
def read_status(
    client_region: Annotated[
        str | None,
        Header(alias='X-Client-Region', max_length=20),
    ] = None,
):
    return {'region': client_region}`}),(0,x.jsx)(`p`,{children:`Здесь мы читаем только один входной header. Annotated связывает тип значения со сведениями FastAPI, Header объявляет источник, alias задаёт точное имя, а None делает отсутствие допустимым. Ограничение длины относится к валидации входа, а не к строковой обработке после получения значения.`}),(0,x.jsx)(`p`,{children:`Это похоже на поле в бланке с отдельной надписью для внешнего участника: внутри программы мы называем значение client_region, а на форме запроса оно подписано X-Client-Region. Надпись помогает сопоставлению, но не меняет само значение. Как и любой вход клиента, заголовок остаётся непроверенным утверждением, а не подтверждением личности или права доступа.`}),(0,x.jsx)(_,{code:`incoming_header = None
if incoming_header is None:
    body_value = None
else:
    body_value = incoming_header`,steps:[{line:0,note:`Мы рассматриваем запрос без X-Client-Region.`,vars:{incoming_header:`None`}},{line:1,note:`Сравнение с None истинно только для отсутствующего значения.`,vars:{incoming_header:`None`}},{line:2,note:`В JSON-поле попадает None, который сериализуется как null.`,vars:{body_value:`None`}}]}),(0,x.jsx)(`p`,{children:`Трассировка показывает только различие отсутствующего заголовка и пустой строки. Для пустой строки условие было бы ложным, а body сохранил бы пустое значение. Мы не превращаем его молча в None и не придумываем дополнительную нормализацию, которой нет в договоре.`})]}),(0,x.jsxs)(s,{number:`03`,title:`Ограничение длины срабатывает до обработчика`,children:[(0,x.jsx)(o,{children:`Строковый header всё равно приходит извне. Если договор допускает не больше 64 символов, FastAPI должен проверить длину на входе, до выполнения кода маршрута.`}),(0,x.jsx)(`p`,{children:`Короткая строка попадает в аргумент без изменения. Значение длиннее лимита отклоняется как невалидный HTTP-запрос, обычно с ответом 422. В таком случае функция маршрута не выполняется, поэтому она не возвращает тело успешного запроса и не устанавливает собственный диагностический header.`}),(0,x.jsx)(`p`,{children:`Не стоит обрезать вход до допустимой длины. Такое решение скрывает нарушение договора и превращает одно значение в другое. Не стоит и проверять только истинность строки: пустая строка и отсутствие заголовка различаются, хотя оба значения могут выглядеть пустыми в условии if not value.`}),(0,x.jsx)(t,{code:`if not client_region:
    client_region = 'default'
if len(client_region) > 20:
    client_region = client_region[:20]`,question:`Что в этом фрагменте скрывает исходное значение запроса?`,options:[`Пустая строка приравнивается к отсутствию, а длинный ввод незаметно обрезается`,`FastAPI не может передать строку в функцию`,`Header всегда превращает пустую строку в None`],correctIndex:0,explanation:`Мы сохраняем разницу между None и пустой строкой, а длину задаём как правило входной валидации. Тогда слишком длинный запрос отклоняется, вместо того чтобы незаметно изменить значение.`,fix:`client_region: Annotated[
    str | None,
    Header(alias='X-Client-Region', max_length=20),
] = None`}),(0,x.jsx)(`p`,{children:`На будущей практике мы проверим четыре ситуации отдельно: header отсутствует, содержит обычную строку, передан пустым и превышает 64 символа. Для первых трёх ожидаем успешный путь и разные значения в body; длинный ввод должен быть отклонён ещё до обработчика.`}),(0,x.jsx)(l,{question:`Какой результат отличает отсутствующий header от переданного пустым?`,options:[`Первый даёт None, второй остаётся пустой строкой`,`Оба обязательно превращаются в строку 'unknown'`,`Первый вызывает 422, второй всегда 404`],correctIndex:0,explanation:`Мы оставляем оба случая различимыми, если договор специально не вводит другую обработку.`}),(0,x.jsx)(`p`,{children:`Мы не выводим причину отказа из клиентского сообщения один к одному. FastAPI сообщает, что запрос не прошёл проверку, но текст ответа может зависеть от версии библиотек. Для нашего контракта важны граница длины и status 422. Слишком длинную строку мы не принимаем и не превращаем в более короткую.`})]}),(0,x.jsxs)(s,{number:`04`,title:`Response добавляет метаданные к обычному JSON`,children:[(0,x.jsx)(o,{children:`Входной Header читается из запроса. Объект Response передаётся в обратном направлении и позволяет настроить заголовки ответа, не заменяя JSON-body.`}),(0,x.jsx)(`p`,{children:`Мы можем принять параметр response: Response, добавить в response.headers собственную метку и вернуть словарь. FastAPI использует настроенные status code и headers при формировании итогового ответа, а обычное значение по-прежнему сериализует в JSON. Если у маршрута есть response_model, он продолжает фильтровать и преобразовывать возвращённые данные.`}),(0,x.jsx)(b,{caption:`Независимый пример: ревизия каталога`,code:`from fastapi import FastAPI, Response

app = FastAPI()

@app.get('/catalog-status')
def catalog_status(response: Response):
    response.headers['X-Catalog-Revision'] = '2026.10'
    return {'ready': True}`}),(0,x.jsx)(`p`,{children:`Словарь остаётся содержимым ответа, а X-Catalog-Revision сообщает отдельную техническую метку. Это похоже на маршрутный ярлык, который мы крепим к посылке перед отправкой: он помогает понять, откуда пришёл ответ, но не переписывает содержимое коробки. Граница сравнения в том, что FastAPI формирует и сериализует HTTP-ответ, а не физическую посылку.`}),(0,x.jsx)(`p`,{children:`Для Planner серверная версия задаётся приложением. Мы не копируем X-Client-Version в X-Planner-Version: клиент может прислать любое значение, а диагностический ответ должен описывать версию самого Planner. Эта метка не является номером релиза Git и не доказывает, какой код сейчас опубликован.`}),(0,x.jsx)(`p`,{children:`Важно изменить именно тот объект Response, который FastAPI передал обработчику. Если мы настроим временный объект, а затем вернём другой JSONResponse, заголовок на первом объекте не окажется автоматически на втором. Прямой Response передаётся клиенту как готовый ответ и не проходит обычную сериализацию данных через response_model.`}),(0,x.jsx)(`p`,{children:`Значение response.headers задаёт данные ответа, но не клиентское значение из входного запроса. Поэтому мы явно выбираем источник каждого поля: client_version читается из Header, а версия Planner берётся из настроек или константы приложения, определённой для этого ресурса. Оба значения могут сосуществовать в одном обмене, не смешивая роли.`}),(0,x.jsx)(c,{question:`Как выставить серверную диагностическую метку, если клиент прислал свою версию?`,left:{title:`Копировать значение запроса`,code:`X-Planner-Version = X-Client-Version`,note:`Ответ начинает повторять недоверенное утверждение клиента.`},right:{title:`Задать значение приложения`,code:`X-Planner-Version = server value`,note:`Вход и метка сервера остаются независимыми.`},preferred:`right`,explanation:`Мы выбираем серверный источник для X-Planner-Version, а клиентскую строку оставляем только контекстом запроса.`}),(0,x.jsx)(r,{tone:`info`,children:`Не нужен отдельный middleware ради одного маршрута. Метаданные этого ответа относятся к конкретному HTTP-ресурсу.`})]}),(0,x.jsxs)(s,{number:`05`,title:`Новый router остаётся частью того же приложения`,children:[(0,x.jsx)(o,{children:`Первый preferences-ресурс расширяет FastAPI, но не создаёт второй Planner. Мы подключаем один новый APIRouter к существующему приложению и оставляем предметные операции без изменений.`}),(0,x.jsx)(`p`,{children:`Новый маршрут нужен для настройки представления, а не для создания или поиска задачи. Поэтому ему не требуется менять Task-схему, JSON-файл, статистику или команды CLI. В этом шаге view всегда имеет default compact: мы ещё не сохраняем выбор между запросами.`}),(0,x.jsx)(`p`,{children:`Клиентский header становится значением client_version в body, если он был передан. Серверный header X-Planner-Version задаётся независимо. Имя поля body не превращает header в задачу, а наличие нового router не означает, что мы добавили новый сервис или второе состояние.`}),(0,x.jsx)(g,{caption:`Как заголовок проходит через новый GET-ресурс`,children:(0,x.jsxs)(m,{label:`Путь запроса и формирование ответа`,children:[(0,x.jsxs)(f,{title:`HTTP-клиент`,shape:`process`,children:[(0,x.jsx)(`p`,{children:`GET /preferences`}),(0,x.jsx)(`code`,{children:`X-Client-Version?`})]}),(0,x.jsx)(p,{label:`FastAPI читает и проверяет header`}),(0,x.jsx)(f,{title:`Обработчик ресурса`,children:(0,x.jsx)(`p`,{children:`Выбирает default view и переданную версию`})}),(0,x.jsx)(p,{label:`Response задаёт серверный header`}),(0,x.jsxs)(f,{title:`HTTP-ответ`,shape:`process`,children:[(0,x.jsx)(`p`,{children:`JSON: view, client_version`}),(0,x.jsx)(`code`,{children:`X-Planner-Version`})]})]})}),(0,x.jsx)(`p`,{children:`Схема показывает одну последовательность без сохранённого состояния: параметр приходит с запросом, проходит проверку, затем данные body и header ответа формируются по разным правилам. Если вход слишком длинный, проверка останавливает путь до обработчика. Иначе успешный ответ содержит и default-представление, и две независимые части обмена.`}),(0,x.jsx)(`p`,{children:`Мы добавляем router один раз к имеющемуся приложению и сохраняем общий путь запуска. Это не повод оборачивать логику задач в preference-обработчик или создавать ещё один объект FastAPI. Следующее занятие сможет развить этот же ресурс, но текущий результат остаётся небольшим и проверяемым.`})]}),(0,x.jsxs)(s,{number:`06`,title:`Проверяем контракт по частям и сохраняем прежний API`,children:[(0,x.jsx)(o,{children:`HTTP-проверка должна пройти через приложение, а не вызывать функцию маршрута напрямую. Тогда мы увидим валидацию FastAPI, итоговый status, сериализованный body и заголовки.`}),(0,x.jsx)(`p`,{children:`Сначала отправим запрос без X-Client-Version: ожидаем 200, compact, null и серверный X-Planner-Version. Затем передадим обычную строку и пустое значение. Они оба проходят по допустимой длине, но в body должны остаться разными: строка сохраняется, отсутствие превращается в null.`}),(0,x.jsx)(`p`,{children:`После этого отправим значение длиннее 64 символов. Ожидаем 422 до выполнения маршрута. Мы проверяем не точную формулировку ошибки конкретной версии Pydantic, а факт отказа и то, что предметное состояние не изменилось. Поскольку обработчик не запускался, собственный X-Planner-Version от него не ожидаем.`}),(0,x.jsx)(`p`,{children:`В тесте отдельно проверим status_code, response.json() и response.headers. Точный GET /preferences запросим без автоматического перенаправления, чтобы случайный завершающий слеш не скрыл неверный путь. Вызов endpoint как обычной Python-функции здесь не заменит HTTP-проверку: он обойдёт разбор header и автоматический отказ на слишком длинном значении.`}),(0,x.jsx)(`p`,{children:`Для новых проверок используем изолированное хранилище, как в уже знакомых сценариях API. После добавления маршрута повторно читаем задачи и статистику, а затем проверяем CLI на той же архитектуре. Это подтверждает, что preference-запрос не записал значение в JSON и не поменял существующий Task API.`}),(0,x.jsx)(`p`,{children:`Регрессия нужна не потому, что новый endpoint вызывает операции задач. Она подтверждает границу: настройки представления не добавили скрытый импорт Planner-сервиса, отдельный файл данных или общий обработчик, который меняет поведение всех маршрутов. Мы сохраняем короткую цепочку ответственности и проверяем её с обеих сторон.`}),(0,x.jsx)(l,{question:`Что доказывает успешный status 200 сам по себе?`,options:[`Только успешный HTTP-статус, но не правильность body и headers`,`Что все поля JSON и оба заголовка соответствуют договору`,`Что JSON-хранилище не изменилось`],correctIndex:0,explanation:`Мы проверяем статус, тело, заголовки и состояние отдельно: одно наблюдение не заменяет остальные.`}),(0,x.jsx)(n,{points:[(0,x.jsx)(x.Fragment,{children:`Header читает входное значение, а alias задаёт имя HTTP-поля.`}),(0,x.jsx)(x.Fragment,{children:`Отсутствие и пустая строка остаются разными значениями.`}),(0,x.jsx)(x.Fragment,{children:`Ограничение длины отклоняет невалидный запрос до обработчика.`}),(0,x.jsx)(x.Fragment,{children:`Response добавляет серверные headers к обычному JSON-ответу.`}),(0,x.jsx)(x.Fragment,{children:`Client-version не подменяет версию, которую сообщает Planner.`}),(0,x.jsx)(x.Fragment,{children:`Новый ресурс не меняет Task, JSON, stats или CLI.`})]})]}),(0,x.jsxs)(s,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,x.jsx)(o,{children:`Мы добавим один несохраняемый preference-ресурс в текущий StudyHub Planner и подтвердим его HTTP-договор на изолированных данных.`}),(0,x.jsx)(d,{variant:`connected`,items:[{title:`Осмотрим опору`,description:`Текущая сборка приложения и router показывают место для нового GET без второго FastAPI-приложения.`},{title:`Добавим контракт`,description:`GET /preferences возвращает compact, принимает необязательный X-Client-Version и выставляет серверный X-Planner-Version.`},{title:`Проверим границы`,description:`Отсутствующий, обычный, пустой и слишком длинный header дают ожидаемые body, status и headers.`},{title:`Подтвердим регрессию`,description:`Task API, статистика, JSON и CLI продолжают работать без preference-состояния.`}]}),(0,x.jsx)(`p`,{children:`Мы будем опираться на изученные Header и Response, но применим их к новому маршруту. Результат должен показывать разницу между входом клиента и метаданными сервера, а не просто отвечать кодом 200.`}),(0,x.jsx)(`p`,{children:`Отдельно сверим status, JSON и response headers, а для слишком длинного значения убедимся, что запрос остановлен до маршрута. Набор задач и команда CLI останутся прежними. Выбор режима не переживает запрос и не создаёт новую запись; сохранение предпочтения относится к следующему шагу блока.`}),(0,x.jsx)(u,{text:`Добавим GET /preferences с диагностическим header и проверим его контракт вместе с прежними операциями Planner.`})]})]})}export{C as Lesson65};